package com.flippingfriend.companion;
import java.util.ArrayList; import java.util.List;
/** Pure fail-closed application of PortfolioCandidate.expectedSlotHours without economics or selection. */
final class BuyReplacementExpectedSlotOccupancyEvaluator {
 private static final double MIN_SLOT_HOURS=1.0/60.0;
 BuyReplacementExpectedSlotOccupancyEvaluationSet evaluate(BuyReplacementCalibratedDurationEvaluationSet s,long at){if(s==null||at<s.getEvaluatedAt()||s.getEvaluatedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getEvaluations()==null||s.getEvaluations().isEmpty()||!Double.isFinite(s.getEffectiveHorizonHours())||s.getEffectiveHorizonHours()<=0)return null;List<BuyReplacementExpectedSlotOccupancyEvaluation> out=new ArrayList<>(s.getEvaluations().size());for(BuyReplacementCalibratedDurationEvaluation e:s.getEvaluations()){if(!valid(e,s))return null;double completed=e.getBuyProbability()*e.getSellProbability();double stranded=e.getBuyProbability()*(1-e.getSellProbability());double neverBought=1-e.getBuyProbability();double hours=neverBought*s.getEffectiveHorizonHours()+completed*(e.getCalibratedBuyHours()+e.getCalibratedSellHours())+stranded*(e.getCalibratedBuyHours()+s.getEffectiveHorizonHours());double expected=Math.max(MIN_SLOT_HOURS,hours);if(!Double.isFinite(expected)||expected<MIN_SLOT_HOURS)return null;out.add(new BuyReplacementExpectedSlotOccupancyEvaluation(e,expected));}return new BuyReplacementExpectedSlotOccupancyEvaluationSet(s,out,at);}
 private static boolean valid(BuyReplacementCalibratedDurationEvaluation e,BuyReplacementCalibratedDurationEvaluationSet s){return e!=null&&e.getExactRemainderQuantity()==s.getExactRemainderQuantity()&&Double.isFinite(e.getBuyProbability())&&e.getBuyProbability()>0&&e.getBuyProbability()<=1&&Double.isFinite(e.getSellProbability())&&e.getSellProbability()>0&&e.getSellProbability()<=1&&Double.compare(e.getCompletionProbability(),e.getBuyProbability()*e.getSellProbability())==0&&Double.isFinite(e.getCalibratedBuyHours())&&e.getCalibratedBuyHours()>=0&&Double.isFinite(e.getCalibratedSellHours())&&e.getCalibratedSellHours()>=0;}
}
